import { IShortLinkRequest, IShortLinkResponse } from 'features/ShortLink';
import { commonApi } from 'shared/api/commonApi';
import { getCookie } from 'shared/utils/getCookie';

export const shortLinkApi = commonApi.injectEndpoints({
	endpoints: (builder) => ({
		createShortLink: builder.mutation<IShortLinkResponse, IShortLinkRequest>({
			query(body) {
				return {
					url: `short_link/`,
					headers: { 'X-Csrftoken': getCookie('csrftoken') },
					method: 'POST',
					body,
				};
			},
		}),
	}),
	overrideExisting: false,
});

export const { useCreateShortLinkMutation } = shortLinkApi;
