import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Card, Flex, theme } from 'antd';
import cn from 'classnames';

import { AffiliateLink, ShortenedLink, SubIds, useShortLinkSlice } from 'features/ShortLink';
import { useMedia } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink, Page, PageTitle } from 'shared/ui';

import styles from './ShortLink.module.scss';

interface IShortLinkProps extends HTMLAttributes<HTMLDivElement> {}

export const ShortLink: FC<IShortLinkProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const { isLoading, isSuccess } = useShortLinkSlice();
	const {
		token: { colorPrimary },
	} = theme.useToken();
	const isMd = useMedia();
	const isLg = useMedia('lg');

	return (
		<Page {...props} className={cn(className, styles.shortLink)}>
			<PageTitle
				subtitle={t(
					'Сокращайте длинные партнерские ссылки, чтобы сделать их визуально более привлекательными для пользователей. Короткая ссылка остается партнерской и сохраняет все добавленные SubID.',
				)}
				component={
					<ButtonStyleLink size="small" variant="text" color="primary" block={isMd} to={`/${EMainRoutes.TOOLS}`}>
						{t('Все инструменты')}
					</ButtonStyleLink>
				}>
				{t('Shortlink')}
			</PageTitle>

			<Flex gap={20} align="start" vertical={isLg}>
				<Card
					className={styles.affiliate}
					styles={{
						body: {
							padding: 24,
						},
					}}>
					<Flex vertical gap={24}>
						<AffiliateLink />
						<SubIds />
					</Flex>
				</Card>

				<Card
					className={styles.short}
					style={{ borderColor: isSuccess && !isLoading ? colorPrimary : undefined }}
					styles={{
						body: {
							padding: 24,
						},
					}}>
					<ShortenedLink />
				</Card>
			</Flex>
		</Page>
	);
};

export default ShortLink;
