import { FC, useEffect } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, FlexProps, Form, Input, Typography } from 'antd';
import { Formik } from 'formik';
import * as Yup from 'yup';

import { addSubIdsToUrl, useCreateShortLinkMutation, useShortLinkSlice } from 'features/ShortLink';
import { urlValidator } from 'shared/consts';

interface IAffiliateLinkProps extends Omit<FlexProps, 'children'> {}

export const AffiliateLink: FC<IAffiliateLinkProps> = ({ ...props }) => {
	const { t } = useTranslation();

	const [createShortLink, { data, isLoading, isSuccess }] = useCreateShortLinkMutation();
	const { affiliateLink, subIds, setAffiliateLink, setIsLoading, setIsSuccess, setShortLink } = useShortLinkSlice();

	useEffect(() => {
		if (isSuccess) {
			setShortLink(data.short_link);
			setIsSuccess(isSuccess);
		}
	}, [isSuccess, data?.short_link]); // eslint-disable-line

	useEffect(() => {
		setIsLoading(isLoading);
	}, [isLoading]); // eslint-disable-line

	const validationSchema = Yup.object({
		affiliate_link: Yup.string()
			.required(t('Это поле обязательно для заполнения'))
			.matches(urlValidator, t('Введите корректный URL'))
			.max(4096, t('Количество символов не должно превышать {{characters}}', { characters: 4096 })),
	});

	return (
		<Formik
			initialValues={{ affiliate_link: affiliateLink }}
			validationSchema={validationSchema}
			onSubmit={(values) => {
				const affiliateLink = addSubIdsToUrl(values.affiliate_link, subIds);
				setAffiliateLink(affiliateLink);
				createShortLink({ affiliate_link: affiliateLink });
			}}>
			{({ values, errors, touched, handleChange, handleBlur, handleSubmit }) => {
				return (
					<form onSubmit={handleSubmit}>
						<Flex {...props} vertical gap={12}>
							<Typography.Text>{t('Введите партнёрскую длинную ссылку')}</Typography.Text>

							<Flex gap={8}>
								<Form.Item
									style={{ flexGrow: 1 }}
									validateStatus={errors.affiliate_link && touched.affiliate_link ? 'error' : ''}
									help={errors.affiliate_link && touched.affiliate_link && errors.affiliate_link}>
									<Input
										name="affiliate_link"
										placeholder="Длинная ссылка"
										onChange={(e) => {
											setAffiliateLink(e.target.value);
											setShortLink('');
											setIsSuccess(false);
											handleChange(e);
										}}
										onBlur={handleBlur}
										value={affiliateLink}
										disabled={isLoading}
										allowClear
									/>
								</Form.Item>

								<Button
									type="primary"
									htmlType="submit"
									disabled={isLoading || !!Object.keys(errors).length || !values.affiliate_link}>
									{t('Сократить')}
								</Button>
							</Flex>
						</Flex>
					</form>
				);
			}}
		</Formik>
	);
};
