import { ChangeEvent, FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, Input, notification, Typography } from 'antd';

import PlusIcon from 'assets/images/icons/plus.svg?react';
import { useShortLinkSlice } from 'features/ShortLink/hooks/useShortLinkSlice';
import { addSubIdsToUrl } from 'features/ShortLink/utils/addSubIdsToUrl';

interface ISubIdsProps extends HTMLAttributes<HTMLDivElement> {}

export const SubIds: FC<ISubIdsProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { subIds, setSubIds, affiliateLink, setAffiliateLink } = useShortLinkSlice();

	const onSubIdChange = (e: ChangeEvent<HTMLInputElement>, key: string) => {
		const newValues = { ...subIds, [key]: e.target.value };
		setSubIds(newValues);

		try {
			setAffiliateLink(addSubIdsToUrl(affiliateLink, newValues));
		} catch (error) {
			notification.open({
				message: t('Введите корректный URL'),
				type: 'error',
				placement: 'topRight',
				showProgress: true,
				pauseOnHover: true,
			});
		}
	};

	return (
		<Flex {...props} vertical gap={12}>
			<div>
				<Typography.Text>{t('Добавьте SubID')}</Typography.Text>{' '}
				<Typography.Text type="secondary">({t('опционально')})</Typography.Text>
			</div>

			<Flex vertical gap={8}>
				{Object.keys(subIds).map((key) => {
					return (
						<Input
							placeholder={`SubID ${key}`}
							value={subIds[key]}
							onChange={(e) => onSubIdChange(e, key)}
							allowClear
						/>
					);
				})}
			</Flex>

			<Button
				variant="outlined"
				color="primary"
				icon={<PlusIcon width={16} height={16} />}
				disabled={Object.keys(subIds).length >= 3}
				onClick={() => setSubIds({ ...subIds, [Object.keys(subIds).length + 1]: '' })}>
				{t('Добавить SubID')}
			</Button>
		</Flex>
	);
};
