import { useDispatch, useSelector } from 'react-redux';

import { RootState } from 'app/appStore';
import { setAffiliateLink, setIsLoading, setIsSuccess, setShortLink, setSubIds } from 'features/ShortLink';

export const useShortLinkSlice = () => {
	const dispatch = useDispatch();

	return {
		...useSelector((s: RootState) => s.shortLinkSlice),
		setAffiliateLink: (link: string) => dispatch(setAffiliateLink(link)),
		setShortLink: (link: string) => dispatch(setShortLink(link)),
		setIsLoading: (isLoading: boolean) => dispatch(setIsLoading(isLoading)),
		setIsSuccess: (isSuccess: boolean) => dispatch(setIsSuccess(isSuccess)),
		setSubIds: (subIds: Record<string, string>) => dispatch(setSubIds(subIds)),
	};
};
