import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, FlexProps, Input, Typography } from 'antd';

import { useShortLinkSlice } from 'features/ShortLink';
import { CopyButton } from 'shared/ui';

interface IShortenedLinkProps extends Omit<FlexProps, 'children'> {}

export const ShortenedLink: FC<IShortenedLinkProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { shortLink, isLoading, isSuccess } = useShortLinkSlice();

	return (
		<Flex {...props} vertical gap={12}>
			<Typography.Text>{t('Ваша короткая ссылка')}</Typography.Text>

			<Flex gap={8}>
				<Input
					name="affiliate_link"
					placeholder="Короткая ссылка"
					value={isLoading ? t('Сокращаем') + '...' : shortLink}
					disabled={true}
				/>

				<CopyButton
					text={shortLink}
					loading={isLoading}
					disabled={!isSuccess || isLoading}
					variant="solid"
					color="primary"
					style={{ minWidth: 40 }}
				/>
			</Flex>
		</Flex>
	);
};
